use super::*;
use serde_json::{Value,json};
use std::{fs,io::Cursor};
fn hex(s:&str)->Vec<u8>{s.as_bytes().chunks_exact(2).map(|p|u8::from_str_radix(std::str::from_utf8(p).unwrap(),16).unwrap()).collect()}
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn base()->protocol::Ack{protocol::Ack{request_id:1,version:47,numeric_schema:1,capabilities:0x1801006f}}
fn codec()->ActorCodec{ActorCodec::local_experiment(base(),1792).unwrap()}
fn input()->Value{let p=Path::new(env!("CARGO_MANIFEST_DIR"));let v:Value=serde_json::from_slice(&fs::read(p.join("logs/continuation-20261003/r432-catalog-snapshot.json")).unwrap()).unwrap();let b=fs::read(v["input"].as_str().unwrap()).unwrap();assert_eq!(sha(&b),v["input_sha256"].as_str().unwrap().to_ascii_lowercase());serde_json::from_slice(&b).unwrap()}
fn vectors(cfg:&Value,name:&str)->Value{let v=cfg["vectors"].as_array().unwrap().iter().find(|v|v["name"]==name).unwrap();let b=fs::read(v["path"].as_str().unwrap()).unwrap();assert_eq!(sha(&b),v["sha256"].as_str().unwrap().to_ascii_lowercase());serde_json::from_slice(&b).unwrap()}
fn sample()->(ActorIdentity,Vec<u8>,Vec<u8>){let v=vectors(&input()["candidate"],"actor-vectors.json");let q=hex(v["loading_request92_hex"].as_str().unwrap());let b=hex(v["loading_result93_hex"].as_str().unwrap());let r=codec().decode_reply(&b,&q).unwrap();(r.identity.unwrap(),q,b)}
fn observe(r:&Reply)->battle_follow::Observation{use super::super::battle_read;let n=r.catalog().native();let q=battle_read::Request{context:n.request.canonical.context,channel_id:n.request.canonical.channel,world:n.canonical.attachment.as_ref().unwrap().world.clone()};let peer=protocol::extensions::Selected::new(base(),0).unwrap();let mut f=battle_follow::Follower::new_selected(q.clone(),peer).unwrap();f.accept(battle_read::UnvalidatedReply{echo:q,state:battle_read::State::Data,data:n.canonical.data.clone()}).unwrap();f.observation().unwrap().clone()}
fn scope(r:&Reply,o:&battle_follow::Observation)->native::Scope{native::Scope{connection_incarnation:432,context:r.request.catalog.native.canonical.context,channel:r.request.catalog.native.canonical.channel,joined_room:o.data().room.id,room_revision:o.data().room.revision}}
fn from_echo(b:&[u8])->Vec<u8>{let at=92+u32_at(b,84) as usize;let c=&b[at..];let n=&c[92+u32_at(c,84) as usize..];let source=u32_at(n,84) as usize;let id=u32_at(b,8);let mut old=app::header(id,88,180).unwrap();old.extend(&n[16..84]);old.extend(&n[92+source..188+source]);let mut cat=app::header(id,90,264).unwrap();cat.extend(&c[16..84]);cat.extend(old);let mut q=app::header(id,92,348).unwrap();q.extend(&b[16..84]);q.extend(cat);q}
#[test]fn actor_selection_and_old_routes_remain_closed(){assert_eq!(protocol::extensions::KNOWN,255);assert!(ActorCodec::default().maximum_result().is_err());for ext in [0,1024,1280,1536,1792|2048,1792|protocol::extensions::FULL_VIP_DATA]{assert!(ActorCodec::local_experiment(base(),ext).is_err());}let (_,q,_)=sample();assert!(codec().decode_request(&q[84..]).is_err());assert!(protocol::extensions::Selected::new(base(),1792).is_err());}
#[test]fn actor_identity_schema_alias_routes_ranges_and_hashes(){let (i,_,_)=sample();assert_eq!(sha(&[b"LITO-NATIVE-ACTOR-DEPENDENCY-IDENTITY\0".as_slice(),i.bytes()].concat()),"6337830c57f3adaf88e99d744381045ff93f493369cdfc3c6db57e408736e200");for at in [0,2,4,6,8,12,16,17,18,20,536,538,588,640,692,744,746,747,796,848,900]{let mut b=*i.bytes();b[at]^=1;assert!(ActorIdentity::decode(&b).is_err(),"{at}");}for at in [24,56,88,296,336,384,424,464,504,556,608,660,712,764,816,868,920]{let mut b=*i.bytes();b[at..at+32].fill(0);assert!(ActorIdentity::decode(&b).is_err());}let mut b=*i.bytes();b[748..756].copy_from_slice(&u64::MAX.to_be_bytes());assert!(ActorIdentity::decode(&b).is_err());}
#[test]fn actor_header_bound_before_body_and_nested_ids(){let (_,q,_)=sample();struct Only(Cursor<Vec<u8>>);impl Read for Only{fn read(&mut self,b:&mut[u8])->std::io::Result<usize>{assert_eq!(self.0.position(),0,"body read");self.0.read(b)}}for n in [427,codec().maximum_result().unwrap()+1]{let mut h=app::header(u32_at(&q,8),93,428).unwrap();h[4..8].copy_from_slice(&(n as u32).to_be_bytes());assert!(codec().read_reply(&mut Only(Cursor::new(h)),&q).is_err());}let mut bad=q.clone();bad[95]^=1;assert!(codec().decode_request(&bad).is_err());let mut bad=q;bad[179]^=1;assert!(codec().decode_request(&bad).is_err());}
#[test]fn actor_immutable_identity_replacement_requires_retirement(){let (i,q,b)=sample();let c=codec();let r=c.decode_reply(&b,&q).unwrap();let o=observe(&r);let mut data=o.data().clone();let owner=data.personal.player.clone();let member=data.room.members.0.iter_mut().find(|m|m.identity.source==owner.source&&m.identity.id==owner.object).unwrap();member.class=1;assert!(profile_data(&data).is_err());data=o.data().clone();data.actors.0.iter_mut().find(|a|a.entity==data.personal.entity).unwrap().heading=2;assert!(profile_data(&data).is_err());let s=scope(&r,&o);let mut owner=ActorOwner::local_experiment(c).unwrap();let t=owner.stage(s,r).unwrap();let old=owner.begin_renderer(t,&o).unwrap();let mut substituted=c.decode_reply(&b,&q).unwrap();let mut changed=*i.bytes();changed[296]^=1;substituted.identity=Some(ActorIdentity::decode(&changed).unwrap());assert!(owner.stage(s,substituted).is_err());let next=owner.stage(s,c.decode_reply(&b,&q).unwrap()).unwrap();assert!(old.cancellation().load(Ordering::Acquire));assert!(owner.begin_renderer(t,&o).is_err());assert!(owner.begin_renderer(next,&o).is_ok());owner.retire();assert!(!owner.loaded_admission_available());}
#[test]
#[ignore="own pinned actor candidate/replay92/93 and actual synthetic TLS publications; no socket/SQL"]
fn fixed_actor_protocol_and_publication_consumer(){let cfg=input();let c=codec();let mut rows=Vec::new();let mut negatives=Vec::new();let mut receipts=Vec::new();for family in ["candidate","replay"]{let v=vectors(&cfg[family],"actor-vectors.json");let bad=vectors(&cfg[family],"actor-negative-vectors.json");let tls=vectors(&cfg[family],"actor-tls-vectors.json");
    for (name,value) in v.as_object().unwrap().iter().filter(|(n,_)|n.ends_with("_request92_hex")){let q=hex(value.as_str().unwrap());let b=hex(v[name.replace("_request92_hex","_result93_hex")].as_str().unwrap());rows.push(check_row(c,family,name,&q,&b,true));}
    let (identity,q,b)=sample();let r=c.decode_reply(&b,&q).unwrap();let source=r.catalog().native().source.as_ref().unwrap();
    for (name,value) in bad.as_object().unwrap(){let b=hex(value.as_str().unwrap());let rejected=if name.starts_with("invalid_identity"){assert!(ActorIdentity::decode(&b).is_err(),"{name}");"identity structure"}else{match c.decode_request(&b){Err(_)=>"request structure",Ok(q)=>{assert!(q.check_authority(&identity,source).is_err(),"{name}");"dependency/catalog/native proof authority"}}};negatives.push(json!({"family":family,"case":name,"sha256":sha(&b),"rejected_by":rejected,"service_ledger_not_replayed":true}));}
    for key in ["source7_full_actor93","source42_full_actor93"]{for (name,value) in tls[key].as_object().unwrap().iter().filter(|(n,_)|n.ends_with("_result93")){let b=hex(value.as_str().unwrap());let q=hex(tls[key][name.replace("_result93","_request92")].as_str().unwrap());assert_eq!(from_echo(&b),q);let r=c.decode_reply(&b,&q).unwrap();assert_eq!(r.request.catalog.native.canonical.context.key.source_id,if key.starts_with("source7"){7}else{42});rows.push(check_row(c,&format!("{family}-TLS"),name,&q,&b,true));}}
    // Legacy89 captures are qualified only when their entire bytes occur in a
    // surviving93; no standalone89 is silently promoted to actor93 authority.
    for name in ["discovery89_hex","preparing89_hex","loading89_hex","loaded89_hex","active89_hex"]{let bytes=hex(tls[name].as_str().unwrap());assert!( ["source7_full_actor93","source42_full_actor93"].iter().flat_map(|k|tls[*k].as_object().unwrap().iter()).filter(|(n,_)|n.ends_with("_result93")).any(|(_,v)|hex(v.as_str().unwrap())[1304..]==bytes),"{family}/{name}");}
    use super::super::{battle_read,battle_action,battle_operation,battle_window};let peer=protocol::extensions::Selected::new(base(),0).unwrap();let bytes=hex(tls["read61_hex"].as_str().unwrap());let r=battle_read::decode_body_selected(&bytes[16..],peer).unwrap();let mut f=battle_follow::Follower::new_selected(r.echo.clone(),peer).unwrap();f.accept(r).unwrap();let o=f.observation().unwrap().clone();let stamp=battle_window::Stamp::of(&o);assert_eq!(stamp.context.key.source_id,7);
    let read_sha=sha(&bytes);let b=hex(tls["move65_hex"].as_str().unwrap());let length=116+u32_at(&b,120) as usize;let mut q=b[..length].to_vec();q[4..8].copy_from_slice(&(length as u32).to_be_bytes());q[12..14].copy_from_slice(&64u16.to_be_bytes());let guard=battle_action::Guard{stamp,target:None};let moved=battle_operation::read_reply_selected(&mut Cursor::new(&b),guard,&q,peer).unwrap();assert_eq!(moved.disposition,battle_operation::Disposition::Applied);
    let other=tls["source42_full_actor93"].as_object().unwrap().iter().filter(|(n,_)|n.ends_with("_result93")).map(|(_,v)|hex(v.as_str().unwrap())).find(|b|b[1304..]==hex(tls["active89_hex"].as_str().unwrap())).unwrap();let other=c.decode_reply(&other,&from_echo(&other)).unwrap();let borrowed=battle_action::Guard{stamp:battle_window::Stamp::of(&observe(&other)),target:None};assert!(battle_operation::read_reply_selected(&mut Cursor::new(&b),borrowed,&q,peer).is_err());
    receipts.push(json!({"family":family,"READ61_sha256":read_sha,"MOVE65_sha256":sha(&b),"source":stamp.context.key.source_id,"object_u64_hex":format!("{:016X}",stamp.context.key.object_id),"epoch_u64_hex":format!("{:016X}",stamp.context.epoch),"channel":stamp.channel,"room":stamp.world[0],"match":stamp.world[1],"generation":stamp.world[2],"entity":stamp.entity,"life":stamp.life,"revision":stamp.revision,"Applied":true,"foreign_source42_guard_refused":true,"captured_request_verified":false}));
}assert_eq!(negatives.len(),128);assert_eq!(receipts.len(),2);fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r432-actor-publication-details.json"),serde_json::to_vec_pretty(&json!({"state":"FIXED_ACTOR_PROTOCOL_PUBLICATIONS_CONSUMED","rows":rows,"negatives":negatives,"receipts":receipts,"Rust_live_TLS_SQL":false,"LOADED":false})).unwrap()).unwrap();}
fn check_row(c:ActorCodec,family:&str,name:&str,q:&[u8],b:&[u8],provided:bool)->Value{let r=c.decode_reply(b,q).unwrap();assert_eq!(c.encode_request(u32_at(q,8),r.request()).unwrap(),q);let i=r.identity().unwrap();assert_eq!(i.bytes().as_slice(),&b[92..1044]);let q=&r.request().catalog.native.canonical;let data=r.catalog().native().canonical.data.as_ref().map(|d|{let o=observe(&r);assert_eq!(o.data(),d);let s=super::super::battle_window::Stamp::of(&o);json!({"source":s.context.key.source_id,"object_u64_hex":format!("{:016X}",s.context.key.object_id),"epoch_u64_hex":format!("{:016X}",s.context.epoch),"channel":s.channel,"room":s.world[0],"match":s.world[1],"generation":s.world[2],"entity":s.entity,"life":s.life,"revision":s.revision})});json!({"family":family,"case":name,"sha256":sha(b),"source":q.context.key.source_id,"object_u64_hex":format!("{:016X}",q.context.key.object_id),"epoch_u64_hex":format!("{:016X}",q.context.epoch),"channel":q.channel,"room":q.room,"match":q.match_id,"generation":q.generation,"data_owner":data,"provided_request_verified":provided,"captured_TLS_request_verified":false,"actor_identity_exact":true})}
#[test]
#[ignore="real R430 full archive stream + actor93 owner binding, CPU only; ~2GiB read"]
fn fixed_actor_authoritative_body_and_opaque_partial_completion(){let p=Path::new(env!("CARGO_MANIFEST_DIR"));let cfg=input();let (_,q,b)=sample();let c=codec();let r=c.decode_reply(&b,&q).unwrap();let o=observe(&r);let scope=scope(&r,&o);let mut owner=ActorOwner::local_experiment(c).unwrap();let t=owner.stage(scope,r).unwrap();let job=owner.begin_renderer(t,&o).unwrap();
    let snapshot:Value=serde_json::from_slice(&fs::read(p.join("logs/continuation-20261003/r430-base-body-snapshot.json")).unwrap()).unwrap();let root=Path::new(snapshot["root"].as_str().unwrap());let provenance=Path::new(cfg["candidate"]["root"].as_str().unwrap()).join("provenance");
    let mut bad=job.identity().clone();bad.wire[56]^=1;assert!(bad.verify_provenance(&provenance,job.cancellation()).is_err());
    let verified=job.load_body(root,&provenance).unwrap();let slice=verified.render(body::BodyAction::Idle,166).unwrap();assert_eq!(slice.sample().2,1);assert!(verified.render(body::BodyAction::Walk,664).is_err());
    let mut other=ActorOwner::local_experiment(c).unwrap();let ot=other.stage(scope,c.decode_reply(&b,&q).unwrap()).unwrap();let other_job=other.begin_renderer(ot,&o).unwrap();assert!(!slice.matches_job(other_job.inner.native_job()));
    let catalog:Value=serde_json::from_slice(&fs::read(p.join("logs/continuation-20261003/r429-catalog-snapshot.json")).unwrap()).unwrap();let text=Path::new(catalog["root"].as_str().unwrap());let fixture=p.join("target/r425-native-dm564-fixture");let sprites=fixture.join("native-archives");let sources=r::NativeSources{map_root:fixture.join("native-map"),archive_root:sprites.clone()};
    let effects=action::NativeActionSnapshot::load_firepot(job.source_plan(),text,&sprites,job.identity().catalog().action_pins(),38,job.cancellation()).unwrap();
    let catalog=job.verify_catalog(text).unwrap();let assets=r::NativeResourceAdapter::pinned_inspection().load_static(&sources,job.source_plan(),Default::default(),job.cancellation()).unwrap();let effect=effects.render_catalog_millis(83,job.cancellation()).unwrap();
    let completion=job.finish_partial(catalog,verified.clone(),assets,vec![effect],slice).unwrap();assert!(other.complete_partial(ot,completion).is_err());
    let job=owner.begin_renderer(t,&o).unwrap();let catalog=job.verify_catalog(text).unwrap();let assets=r::NativeResourceAdapter::pinned_inspection().load_static(&sources,job.source_plan(),Default::default(),job.cancellation()).unwrap();let effect=effects.render_catalog_millis(83,job.cancellation()).unwrap();let slice=verified.render(body::BodyAction::Walk,166).unwrap();let rgba_sha=sha(slice.canvas().rgba());let token=job.inner.native_job().cancellation_token();let completion=job.finish_partial(catalog,verified,assets,vec![effect],slice).unwrap();owner.complete_partial(t,completion).unwrap();assert!(owner.partial_available());assert!(!owner.loaded_admission_available());owner.retire();assert!(token.load(Ordering::Acquire));assert!(!owner.partial_available());
    fs::write(p.join("logs/continuation-20261003/r432-actor-body-details.json"),serde_json::to_vec_pretty(&json!({"state":"REAL_ACTOR_DEPENDENCY_PARTIAL_VERIFIED","identity_digest":sha(&[b"LITO-NATIVE-ACTOR-DEPENDENCY-IDENTITY\0".as_slice(),sample().0.bytes()].concat()),"body_rgba_sha256":rgba_sha,"profile1_class0_sex0":true,"explicit_study_not_weapon_authority":true,"base_archives_streamed":true,"raw_decoded_text_and_selected_member_ranges_verified":true,"four_pinned_MISS_then_base_members":true,"cross_owner_completion_refused":true,"opaque_partial_accepted":true,"retire_cancels":true,"LOADED":false,"GUI":0,"SQL":false})).unwrap()).unwrap();}
